 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            objects.append((color, cells))
    # Pack objects toward the right, starting with those already farthest right.
    objects.sort(key=lambda item: max(c for _, c in item[1]), reverse=True)
    occupied = set()
    placed = []
    for color, cells in objects:
        shift = 0
        while True:
            nxt = shift + 1
            if any(c + nxt >= w or (r, c + nxt) in occupied for r, c in cells):
                break
            shift = nxt
        moved = [(r, c + shift) for r, c in cells]
        occupied.update(moved)
        placed.append((color, moved))
    out = [[0] * w for _ in range(h)]
    for color, cells in placed:
        for r, c in cells:
            out[r][c] = color
    return out
